'use strict';

var gifRegexp = /^GIF[]a/;
function isGIF (buffer) {
  var signature = buffer.toString('ascii', , );
  return (gifRegexp.test(signature));
}

function calculate(buffer) {
  return {
    'width': buffer.readUIntLE(),
    'height': buffer.readUIntLE()
  };
}

module.exports = {
  'detect': isGIF,
  'calculate': calculate
};
